INSERT INTO `course_videos` (`id`, `course_id`, `title`, `description`, `created_at`, `updated_at`) VALUES
(398, '3', 'Develop skills for real career growth', '<p>Cutting-edge curriculum designed in guidance with industry and academia to develop job-ready skills</p>', '2025-09-10 21:59:22', '2025-09-10 21:59:22'),
(399, '3', 'Learn from experts active in their field, not out-of-touch trainers', '<p>Leading practitioners who bring current best practices and case studies to sessions that fit into your work schedule.</p>', '2025-09-10 21:59:22', '2025-09-10 21:59:22'),
(400, '3', 'Learn by working on real-world problems', '<p>Capstone projects involving real world data sets with virtual labs for hands-on learning</p>', '2025-09-10 21:59:22', '2025-09-10 21:59:22'),
(401, '3', 'Structured guidance ensuring learning never stops', '<p>24x7 Learning support from mentors and a community of like-minded peers to resolve any conceptual doubts</p>', '2025-09-10 21:59:22', '2025-09-10 21:59:22'),
(454, '10', 'Develop skills for real career growth', '<p>Cutting-edge curriculum designed in guidance with industry and academia to develop job-ready skills</p>', '2025-09-11 02:43:30', '2025-09-11 02:43:30'),
(455, '10', 'Learn from experts active in their field, not out-of-touch trainers', '<p>Leading practitioners who bring current best practices and case studies to sessions that fit into your work schedule.</p>', '2025-09-11 02:43:30', '2025-09-11 02:43:30'),
(456, '10', 'Learn by working on real-world problems', '<p>Capstone projects involving real world data sets with virtual labs for hands-on learning</p>', '2025-09-11 02:43:30', '2025-09-11 02:43:30'),
(457, '10', 'Structured guidance ensuring learning never stops', '<p>24x7 Learning support from mentors and a community of like-minded peers to resolve any conceptual doubts</p>', '2025-09-11 02:43:30', '2025-09-11 02:43:30'),
(625, '9', 'Acquire skills that foster genuine career advancement', '<p>A state-of-the-art curriculum developed in collaboration with industry leaders and academic institutions to cultivate job-ready competencies.&nbsp;</p>', '2025-09-13 01:55:36', '2025-09-13 01:55:36'),
(626, '9', 'Gain insights from professionals actively engaged in their fields, rather than disconnected instructors.', '<p>Esteemed practitioners who share contemporary best practices and relevant case studies during sessions that accommodate your work commitments.</p>', '2025-09-13 01:55:36', '2025-09-13 01:55:36'),
(627, '9', 'Engage in practical problem-solving experiences.', '<p>Capstone projects utilizing real-world data sets, complemented by virtual labs for experiential learning.</p>', '2025-09-13 01:55:36', '2025-09-13 01:55:36'),
(628, '8', 'Comprehensive Curriculum', '<p>Our bootcamp covers all aspects of the PMI-ACP® certification, including the latest PMBOK guidelines, ensuring you have the knowledge to succeed.</p>', '2025-09-13 01:56:23', '2025-09-13 01:56:23'),
(629, '8', 'Expert Instructors', '<p>Learn from experienced PMI-ACP®-certified instructors who bring real-world project management experience and insights to the course.</p>', '2025-09-13 01:56:23', '2025-09-13 01:56:23'),
(630, '8', 'Flexible Learning', '<p>With our online format, you can study at your own pace and fit your learning around your schedule, making it ideal for busy professionals.</p>', '2025-09-13 01:56:23', '2025-09-13 01:56:23'),
(631, '8', 'Interactive Experience', '<p>Engage with interactive content, participate in live Q&amp;A sessions, and join a community of fellow learners to enhance your learning experience.</p>', '2025-09-13 01:56:23', '2025-09-13 01:56:23'),
(632, '6', 'Enhance your abilities for genuine career advancement', '<p>A state-of-the-art curriculum crafted in collaboration with industry leaders and academic institutions to cultivate job-ready competencies</p>', '2025-09-13 01:56:59', '2025-09-13 01:56:59'),
(633, '6', 'Gain insights from professionals actively engaged in their fields, rather than disconnected instructors', '<p>Top-tier practitioners who share contemporary best practices and relevant case studies during sessions that accommodate your work commitments.</p>', '2025-09-13 01:56:59', '2025-09-13 01:56:59'),
(634, '6', 'Engage in solving actual industry challenges', '<p>Capstone projects utilizing real-world data sets, complemented by virtual labs for practical experience</p>', '2025-09-13 01:56:59', '2025-09-13 01:56:59'),
(635, '6', 'Systematic support ensuring continuous learning', '<p>24/7 assistance from mentors and a network of like-minded individuals to address any conceptual uncertainties</p>', '2025-09-13 01:56:59', '2025-09-13 01:56:59'),
